// CollectFields tells the query-builder to eagerly load connected nodes by resolver context.
func (_q *WorkspaceQuery) CollectFields(ctx context.Context, satisfies ...string) (*WorkspaceQuery, error) {
	fc := graphql.GetFieldContext(ctx)
	if fc == nil {
		return _q, nil
	}
	if err := _q.collectField(ctx, false, graphql.GetOperationContext(ctx), fc.Field, nil, satisfies...); err != nil {
		return nil, err
	}
	return _q, nil
}

func (_q *WorkspaceQuery) collectField(ctx context.Context, oneNode bool, opCtx *graphql.OperationContext, collected graphql.CollectedField, path []string, satisfies ...string) error {
	path = append([]string(nil), path...)
	var (
		unknownSeen    bool
		fieldSeen      = make(map[string]struct{}, len(workspace.Columns))
		selectedFields = []string{workspace.FieldID}
	)
	for _, field := range graphql.CollectFields(opCtx, collected.Selections, satisfies) {
		switch field.Name {
		case "createdAt":
			if _, ok := fieldSeen[workspace.FieldCreatedAt]; !ok {
				selectedFields = append(selectedFields, workspace.FieldCreatedAt)
				fieldSeen[workspace.FieldCreatedAt] = struct{}{}
			}
		case "updatedAt":
			if _, ok := fieldSeen[workspace.FieldUpdatedAt]; !ok {
				selectedFields = append(selectedFields, workspace.FieldUpdatedAt)
				fieldSeen[workspace.FieldUpdatedAt] = struct{}{}
			}
		case "projectID":
			if _, ok := fieldSeen[workspace.FieldProjectID]; !ok {
				selectedFields = append(selectedFields, workspace.FieldProjectID)
				fieldSeen[workspace.FieldProjectID] = struct{}{}
			}
		case "name":
			if _, ok := fieldSeen[workspace.FieldName]; !ok {
				selectedFields = append(selectedFields, workspace.FieldName)
				fieldSeen[workspace.FieldName] = struct{}{}
			}
		case "body":
			if _, ok := fieldSeen[workspace.FieldBody]; !ok {
				selectedFields = append(selectedFields, workspace.FieldBody)
				fieldSeen[workspace.FieldBody] = struct{}{}
			}
		case "id":
		case "__typename":
		default:
			unknownSeen = true
		}
	}
	if !unknownSeen {
		_q.Select(selectedFields...)
	}
	return nil
}

